// dico-pratiques.js : traductions anglaises des textes de pratiques.js (français à gauche, anglais à droite).
// Les {0}, {1}… sont remplacés par les valeurs que passe le code : T("… {0} …", valeur).
EN_AJOUTER([
  ["Les immeubles anciens du centre-ville sont solides : la plupart ont plus de cent ans et tiennent toujours debout.", "The old buildings in the town centre are sturdy: most are over a hundred years old and still standing."],
  ["On construisait mieux autrefois", "They built better in the old days"],
  ["Les immeubles fragiles de la même époque ont été démolis ou se sont effondrés : on ne voit que ceux qui ont tenu", "The fragile buildings of the same period were demolished or collapsed: we only see those that held up"],
  ["Les matériaux anciens durcissent avec le temps", "Old materials harden with time"],
  ["Les immeubles qu'on peut observer aujourd'hui sont ceux qui ont résisté. Les autres, peut-être nombreux, ont disparu et ne comptent plus dans l'impression d'ensemble.", "The buildings we can see today are the ones that have survived. The others, perhaps numerous, have disappeared and no longer count in the overall impression."],
  ["Les chansons des années 1980 qu'on entend encore à la radio sont presque toutes excellentes. La musique était meilleure à l'époque.", "The songs from the 1980s that you still hear on the radio are almost all excellent. Music was better back then."],
  ["Les radios ne rediffusent que les chansons qui ont plu ; les chansons oubliées de la même époque, bien plus nombreuses, n'y passent plus", "Radio stations only replay the songs people liked; the forgotten songs of the same era, far more numerous, no longer get played"],
  ["Les musiciens des années 1980 étaient plus doués", "Musicians in the 1980s were more talented"],
  ["Les goûts musicaux ne changent pas", "Musical tastes do not change"],
  ["On compare les meilleures chansons d'hier, filtrées par le temps, à toute la production d'aujourd'hui, pas encore filtrée.", "We are comparing the best songs of yesterday, filtered by time, with all of today’s output, which has not yet been filtered."],
  ["Une salle de sport interroge ses clients inscrits depuis plus de deux ans : 90 % se disent satisfaits. Elle en conclut que presque tous ses clients sont satisfaits.", "A gym surveys its members of more than two years’ standing: 90% say they are satisfied. It concludes that almost all its members are satisfied."],
  ["90 %, c'est une large majorité", "90% is a large majority"],
  ["Les clients mécontents sont partis avant deux ans : l'enquête n'interroge que ceux qui sont restés", "The unhappy members left before two years: the survey only asks those who stayed"],
  ["Les clients mentent dans les enquêtes", "Members lie in surveys"],
  ["En n'interrogeant que les clients restés, l'enquête écarte ceux qui avaient le plus de raisons d'être insatisfaits.", "By surveying only the members who stayed, the survey leaves out those who had the most reason to be dissatisfied."],
  ["Tous les champions d'échecs interrogés par un magazine jouaient déjà enfant. Le magazine en conclut que commencer tôt suffit pour devenir champion.", "All the chess champions interviewed by a magazine had already been playing as children. The magazine concludes that starting early is enough to become a champion."],
  ["Les échecs demandent des années d'entraînement", "Chess takes years of practice"],
  ["Le magazine n'a pas interrogé les nombreux joueurs qui ont commencé enfant sans devenir champions", "The magazine did not interview the many players who started as children without becoming champions"],
  ["Les champions se souviennent mal de leur enfance", "Champions remember their childhood poorly"],
  ["Pour savoir si commencer tôt suffit, il faudrait regarder tous ceux qui ont commencé tôt, et pas seulement ceux qui ont réussi.", "To know whether starting early is enough, we would have to look at everyone who started early, not only those who succeeded."],
  ["la qualité du sommeil", "sleep quality"],
  ["le niveau de stress", "stress level"],
  ["Le petit-déjeuner est le repas le plus important de la journée.", "Breakfast is the most important meal of the day."],
  ["Un livre papier vaut mieux qu'un livre numérique.", "A paper book is better than an e-book."],
  ["Les vacances à la montagne valent mieux que les vacances à la mer.", "Holidays in the mountains are better than holidays at the seaside."],
  ["Le café est meilleur que le thé.", "Coffee is better than tea."],
  ["Il vaut mieux se lever tôt, même le week-end.", "It is better to get up early, even at the weekend."],
  ["Un film en version originale vaut mieux qu'un film doublé.", "A film in its original language is better than a dubbed film."],
  ["Il vaut mieux vivre en ville qu'à la campagne.", "It is better to live in a town than in the countryside."],
  ["Avoir un animal de compagnie rend plus heureux.", "Having a pet makes you happier."],
  ["Il faut ranger sa maison tous les jours.", "You should tidy your house every day."],
  ["Les jeux de société sont plus amusants en famille qu'entre amis.", "Board games are more fun with family than with friends."],
  ["Il vaut mieux voyager en train qu'en avion quand c'est possible.", "It is better to travel by train than by plane when possible."],
  ["La musique est plus agréable en concert qu'enregistrée.", "Music is more enjoyable live than recorded."],
  ["plutôt pas d'accord", "rather disagree"],
  ["plutôt d'accord", "rather agree"],
  ["partagé", "divided"],
  ["Les avions de Wald", "Wald’s planes"],
  ["Les avions qui reviennent de mission sont criblés d'impacts. Où renforcer le blindage ? Puis quatre autres situations où l'on ne voit que les survivants.", "Planes returning from missions are riddled with bullet holes. Where should the armour go? Then four more situations in which we only see the survivors."],
  ["Pendant la Seconde Guerre mondiale, on relève les impacts de balles sur les bombardiers qui rentrent de mission. Ils sont nombreux sur les ailes et le fuselage, rares sur les moteurs et le poste de pilotage. Où faut-il renforcer le blindage ?", "During the Second World War, the bullet holes on bombers returning from missions are recorded. They are numerous on the wings and fuselage, rare on the engines and cockpit. Where should the armour be reinforced?"],
  ["Schéma illustratif : les impacts relevés sur les avions revenus.", "Illustration: the hits recorded on the planes that came back."],
  ["Sur les ailes et le fuselage, là où les impacts sont nombreux", "On the wings and fuselage, where the hits are numerous"],
  ["Sur les moteurs et le poste de pilotage, là où les impacts sont rares", "On the engines and cockpit, where the hits are rare"],
  ["Partout de la même façon", "Equally everywhere"],
  ["Les avions observés sont ceux qui sont revenus. S'ils portent peu d'impacts sur les moteurs, c'est que les avions touchés là ne sont pas revenus : c'est là qu'il faut blinder. Les impacts visibles montrent au contraire les endroits où un avion peut être touché et rentrer quand même.", "The planes observed are the ones that came back. If they have few hits on the engines, it is because planes hit there did not come back: that is where the armour is needed. The visible hits show, on the contrary, the places where a plane can be hit and still return."],
  ["Votre choix", "Your choice"],
  ["Qu'est-ce qui explique le mieux cette impression ?", "What best explains this impression?"],
  ["Ce qu'on ne voit pas", "What we do not see"],
  ["Le biais du survivant consiste à tirer des conclusions des seuls cas qui ont franchi un filtre (les avions revenus, les entreprises qui ont réussi, les immeubles encore debout), en oubliant ceux que le filtre a éliminés.", "Survivorship bias is drawing conclusions from only the cases that passed through a filter (the planes that returned, the businesses that succeeded, the buildings still standing), while forgetting those the filter eliminated."],
  ["L'histoire des avions est attribuée au statisticien Abraham Wald, qui travaillait pour l'armée américaine. L'idée est fondée, mais l'anecdote a été enjolivée : ses mémorandums ne font aucune recommandation de blindage, et aucun croquis d'avion de sa main n'est connu (Feature Column de l'American Mathematical Society, 2016).", "The story of the planes is attributed to the statistician Abraham Wald, who worked for the US military. The idea is sound, but the anecdote has been embellished: his memoranda make no armour recommendation, and no sketch of a plane in his hand is known (American Mathematical Society Feature Column, 2016)."],
  ["Biais du survivant", "Survivorship bias"],
  ["Fabriquer un résultat", "Manufacturing a result"],
  ["Une tisane sans aucun effet, quarante participants. Changez de mesure, de sous-groupe, retirez des valeurs, ajoutez des participants… jusqu'à obtenir un résultat « significatif ».", "A herbal tea with no effect whatsoever, forty participants. Change the measure, the subgroup, remove values, add participants… until you get a “significant” result."],
  ["Vous êtes chercheur. Vingt participants ont bu une tisane, vingt autres de l'eau chaude. Les données sont simulées : la tisane n'a aucun effet, sur rien. Votre but, pourtant : un résultat « significatif », c'est-à-dire p < 0,05.", "You are a researcher. Twenty participants drank a herbal tea, twenty others hot water. The data are simulated: the tea has no effect, on anything. Your goal, nevertheless: a “significant” result, that is, p < 0.05."],
  ["Mesure", "Measure"],
  ["Participants", "Participants"],
  ["Tous", "Everyone"],
  ["Femmes seulement", "Women only"],
  ["Hommes seulement", "Men only"],
  ["Valeurs extrêmes (au-delà de 2 écarts-types)", "Outliers (beyond 2 standard deviations)"],
  ["Gardées", "Kept"],
  ["Retirées", "Removed"],
  ["Ajouter 10 participants par groupe", "Add 10 participants per group"],
  ["({0} par groupe)", "({0} per group)"],
  ["Trop peu de participants dans ce sous-groupe.", "Too few participants in this subgroup."],
  ["Différence entre les groupes, sur {0} : {1} écart-type.", "Difference between the groups, on {0}: {1} standard deviations."],
  ["analyse essayée", "analysis tried"],
  ["analyses essayées", "analyses tried"],
  ["« Significatif ! » La tisane semble agir… sur des données où elle n'a aucun effet.", "“Significant!” The tea seems to work… on data where it has no effect."],
  ["Publier ce résultat", "Publish this result"],
  ["Abandonner et voir le bilan", "Give up and see the summary"],
  ["Vous avez obtenu un résultat « significatif » en {0}, sans fraude : seulement des choix d'analyse, chacun défendable isolément.", "You obtained a “significant” result in {0}, without fraud: just analysis choices, each defensible on its own."],
  ["Vous n'avez pas obtenu de résultat significatif en {0}. Un chercheur obstiné y serait souvent parvenu.", "You did not obtain a significant result in {0}. A persistent researcher would often have managed it."],
  ["Sur 1 000 études simulées à l'instant, toutes sur une tisane sans effet, un chercheur qui essaie les trois mesures, les trois sous-groupes, avec ou sans valeurs extrêmes, puis ajoute dix participants par groupe faute de résultat, obtient p < 0,05 dans {0} % des cas. Avec une seule analyse fixée d'avance, ce serait 5 %.", "Out of 1,000 studies just simulated, all on a herbal tea with no effect, a researcher who tries the three measures, the three subgroups, with or without outliers, then adds ten participants per group for lack of a result, gets p < 0.05 in {0}% of cases. With a single analysis fixed in advance, it would be 5%."],
  ["Les degrés de liberté du chercheur", "The researcher’s degrees of freedom"],
  ["Simmons, Nelson et Simonsohn (2011) ont montré qu'en combinant quelques libertés d'analyse de ce genre, on obtient un faux positif dans 61 % des cas. Ils ont ainsi « démontré » qu'écouter une chanson des Beatles rajeunissait les auditeurs.", "Simmons, Nelson and Simonsohn (2011) showed that by combining a few analytical freedoms of this kind, you get a false positive in 61% of cases. They thereby “demonstrated” that listening to a Beatles song made listeners younger."],
  ["Les remèdes : déclarer à l'avance la mesure, l'échantillon et l'analyse (préenregistrement), publier toutes les analyses essayées, et se méfier d'un résultat isolé, surtout s'il est surprenant.", "The remedies: declare the measure, the sample and the analysis in advance (preregistration), publish all the analyses tried, and distrust an isolated result, especially a surprising one."],
  ["Taille de l'échantillon", "Sample size"],
  ["Nouvelles données", "New data"],
  ["La foule intérieure", "The inner crowd"],
  ["Estimez six quantités. Puis supposez que votre première estimation soit fausse, et faites-en une seconde. La moyenne des deux est-elle plus juste ?", "Estimate six quantities. Then suppose your first estimate is wrong, and make a second one. Is the average of the two more accurate?"],
  ["Votre première estimation : {0}. Supposez qu'elle soit fausse. Pourquoi le serait-elle ? Était-elle plutôt trop haute ou trop basse ? Faites une seconde estimation, différente, à partir de cette nouvelle hypothèse.", "Your first estimate: {0}. Suppose it is wrong. Why might it be? Was it rather too high or too low? Make a second, different estimate based on this new assumption."],
  ["Votre seconde estimation", "Your second estimate"],
  ["Noté. La réponse viendra au second tour.", "Noted. The answer will come in the second round."],
  ["Noté.", "Noted."],
  ["La moyenne de vos deux estimations a fait mieux que la première dans {0} cas sur {1}. Erreur moyenne, en ordres de grandeur : première estimation {2}, seconde {3}, moyenne des deux {4}.", "The average of your two estimates did better than the first in {0} cases out of {1}. Average error, in orders of magnitude: first estimate {2}, second {3}, average of the two {4}."],
  ["{0} : {1} ; vous : {2} puis {3}, moyenne {4}", "{0}: {1}; you: {2} then {3}, average {4}"],
  ["La moyenne de plusieurs estimations indépendantes est souvent plus juste que chacune, parce que leurs erreurs se compensent en partie. Une seule personne peut imiter cet effet : Herzog et Hertwig (2009) ont montré qu'une seconde estimation faite après avoir cherché pourquoi la première serait fausse, moyennée avec elle, est plus juste qu'une simple seconde estimation.", "The average of several independent estimates is often more accurate than any single one, because their errors partly cancel out. A single person can mimic this effect: Herzog and Hertwig (2009) showed that a second estimate made after looking for reasons why the first might be wrong, averaged with it, is more accurate than a simple second estimate."],
  ["Le gain existe, mais il reste modeste : sur 1,2 million de participants, van Dolder et van den Assem trouvent qu'il est bien inférieur à celui que procure l'avis d'une autre personne. Demander à quelqu'un d'autre reste le meilleur moyen.", "The gain exists, but it remains modest: on 1.2 million participants, van Dolder and van den Assem find it is well below what the opinion of another person provides. Asking someone else is still the best way."],
  ["La cécité au choix", "Choice blindness"],
  ["Donnez votre avis sur douze affirmations sans enjeu, puis expliquez quelques-unes de vos réponses. À ne faire qu'une fois : le principe se dévoile à la fin.", "Give your opinion on twelve low-stakes statements, then explain some of your answers. Do this only once: the principle is revealed at the end."],
  ["Vous avez déjà fait cette expérience : vous en connaissez le principe, qui ne peut plus vous surprendre. Vous pouvez la refaire, ou la proposer à quelqu'un d'autre.", "You have already done this experiment: you know the principle, which can no longer surprise you. You can do it again, or suggest it to someone else."],
  ["Recommencer quand même", "Start over anyway"],
  ["Vos réponses", "Your answers"],
  ["Voici quatre de vos réponses. Pour chacune, expliquez en une phrase pourquoi vous pensez cela.", "Here are four of your answers. For each one, explain in a sentence why you think so."],
  ["Votre réponse : {0} sur 9 ({1}).", "Your answer: {0} out of 9 ({1})."],
  ["Pourquoi ?", "Why?"],
  ["Ce n'est pas ce que j'ai répondu", "That is not what I answered"],
  ["Signalé", "Flagged"],
  ["Terminer", "Finish"],
  ["Révélation", "The reveal"],
  ["Deux des quatre réponses affichées avaient été inversées : on vous montrait l'avis contraire du vôtre. Vous en avez signalé {0}.", "Two of the four answers shown had been reversed: you were shown the opposite of your own opinion. You flagged {0} of them."],
  ["« {0} » : vous aviez répondu {1}, on vous a montré {2}.", "“{0}”: you had answered {1}, you were shown {2}."],
  ["Repéré.", "Spotted."],
  ["Non repéré.", "Not spotted."],
  ["Défendre un choix qu'on n'a pas fait", "Defending a choice you did not make"],
  ["Hall, Johansson et Strandberg (2012) ont fait remplir à 160 personnes un questionnaire d'opinions politiques, puis leur ont montré certaines réponses inversées en secret. 69 % n'ont pas repéré au moins une des deux inversions, et 53 % ont défendu sans ambiguïté l'avis opposé au leur.", "Hall, Johansson and Strandberg (2012) had 160 people fill in a questionnaire of political opinions, then showed them some answers secretly reversed. 69% did not spot at least one of the two reversals, and 53% unambiguously defended the opinion opposite to their own."],
  ["Nous connaissons nos raisons moins bien que nous le croyons : face à une réponse qu'on nous attribue, nous construisons souvent une justification après coup. Ici, sur des sujets sans enjeu et avec un seul essai, le résultat ne mesure rien de précis : c'est une démonstration, pas un test.", "We know our reasons less well than we think: faced with an answer attributed to us, we often construct a justification after the fact. Here, on low-stakes subjects and with a single attempt, the result measures nothing precise: it is a demonstration, not a test."],
  ["Cette expérience ne se fait qu'une fois : maintenant que vous en connaissez le principe, vous seriez sur vos gardes. Vous pouvez la proposer à quelqu'un d'autre.", "This experiment can only be done once: now that you know the principle, you would be on your guard. You can suggest it to someone else."],
  ["Pendant un débat, une émission ou un repas, cochez chaque sophisme que vous entendez. Une ligne, une colonne ou une diagonale complète : bingo. Avec la même adresse, chacun a la même grille.", "During a debate, a programme or a meal, tick each fallacy you hear. A complete row, column or diagonal: bingo. With the same address, everyone has the same card."],
  ["Grille de bingo des sophismes", "Fallacy bingo card"],
  ["Bingo ! Une ligne complète.", "Bingo! A complete line."],
  ["{0} sur 16.", "{0} out of 16."],
  ["case cochée", "box ticked"],
  ["cases cochées", "boxes ticked"],
  ["Grille n° {0} : {1}", "Card no. {0}: {1}"],
  ["Nouvelle grille", "New card"],
  ["Imprimer", "Print"],
  ["Partager cette grille", "Share this card"],
  ["Bingo des sophismes : {0}", "Fallacy bingo: {0}"],
  ["Adresse copiée.", "Address copied."],
  ["Les seize sophismes de cette grille", "The sixteen fallacies on this card"],
  ["Celui qui affirme", "The one who asserts"],
  ["Celui qui doute", "The one who doubts"],
  ["Les deux, chacun pour ce qu'il affirme", "Both, each for what they assert"],
  ["Personne : c'est une affaire de goût", "No one: it is a matter of taste"],
  ["Léo : « Ce bracelet magnétique soulage les douleurs articulaires. » Julie : « J'en doute. »", "Léo: “This magnetic bracelet relieves joint pain.” Julie: “I doubt it.”"],
  ["C'est à Léo, qui affirme un effet, d'apporter des preuves. Julie n'a rien à démontrer en doutant.", "It is up to Léo, who claims an effect, to provide evidence. Julie has nothing to demonstrate by doubting."],
  ["Nora : « Ce restaurant est le meilleur du quartier. » Paul : « Je préfère celui d'en face. »", "Nora: “This restaurant is the best in the neighbourhood.” Paul: “I prefer the one across the road.”"],
  ["Il s'agit de goûts : aucun des deux n'a de preuve à fournir, même si chacun peut donner ses raisons.", "These are matters of taste: neither has any evidence to provide, even if each can give their reasons."],
  ["Marc : « Le nouveau logiciel fait gagner une heure par jour. » Inès : « Faux, il en fait perdre une. »", "Marc: “The new software saves an hour a day.” Inès: “Wrong, it wastes an hour.”"],
  ["Inès ne se contente pas de douter : elle affirme le contraire. Chacun doit appuyer sa propre affirmation.", "Inès is not merely doubting: she asserts the opposite. Each must support their own claim."],
  ["Un vendeur : « Prouvez-moi que ce complément ne marche pas, et je vous rembourse. »", "A salesman: “Prove to me that this supplement doesn’t work, and I’ll refund you.”"],
  ["Le vendeur renverse la charge de la preuve : c'est à lui, qui vante un effet, de le démontrer.", "The salesman reverses the burden of proof: it is up to him, as the one praising an effect, to demonstrate it."],
  ["Sami : « Il a plu toute la journée hier à Lyon. » Clara : « Je ne crois pas. »", "Sami: “It rained all day yesterday in Lyon.” Clara: “I don’t think so.”"],
  ["Sami affirme un fait vérifiable ; c'est à lui de le montrer, par exemple avec un relevé météo. Le doute de Clara n'affirme rien.", "Sami asserts a verifiable fact; it is up to him to show it, for example with a weather record. Clara’s doubt asserts nothing."],
  ["Mathilde : « La Terre tourne autour du Soleil. » Bob : « Je n'y crois pas, prouve-le. »", "Mathilde: “The Earth goes round the Sun.” Bob: “I don’t believe it, prove it.”"],
  ["Mathilde énonce un fait établi depuis des siècles, et dont les preuves sont accessibles à tous : elles ont déjà été apportées. Celui qui conteste un résultat aussi solide doit expliquer en quoi il serait faux.", "Mathilde states a fact established for centuries, whose evidence is accessible to everyone: it has already been provided. Anyone disputing so solid a result must explain why it would be wrong."],
  ["Emma : « Le bleu est la plus belle couleur. » Tom : « Pas du tout, c'est le vert. »", "Emma: “Blue is the most beautiful colour.” Tom: “Not at all, it’s green.”"],
  ["Préférences esthétiques : il n'y a rien à prouver, seulement des goûts à échanger.", "Aesthetic preferences: there is nothing to prove, only tastes to exchange."],
  ["Un élu : « Cette mesure a fait baisser les cambriolages de 30 %. » Un journaliste : « Sur quelles données ? »", "An elected official: “This measure cut burglaries by 30%.” A journalist: “Based on what data?”"],
  ["L'élu avance un chiffre et une cause : à lui de montrer les données et la méthode. La question du journaliste n'affirme rien.", "The official puts forward a figure and a cause: it is up to them to show the data and the method. The journalist’s question asserts nothing."],
  ["Yasmine : « Ce médicament est efficace : il a passé un essai comparatif publié. » Karim : « Je pense que l'essai est truqué. »", "Yasmine: “This drug is effective: it passed a published comparative trial.” Karim: “I think the trial was rigged.”"],
  ["Yasmine a apporté un élément de preuve. Karim affirme une fraude : c'est maintenant à lui d'étayer cette accusation.", "Yasmine has provided a piece of evidence. Karim asserts fraud: it is now up to him to back up this accusation."],
  ["Ali : « Je pense que la réunion de demain va être annulée. » Rose : « Pourquoi ? »", "Ali: “I think tomorrow’s meeting is going to be cancelled.” Rose: “Why?”"],
  ["Une simple prévision, mais c'est quand même à Ali de dire sur quoi il s'appuie, s'il veut être cru.", "A simple prediction, but it is still up to Ali to say what he is basing it on, if he wants to be believed."],
  ["Insulte", "Name-calling"],
  ["Attaque personnelle", "Ad hominem"],
  ["Réponse au ton", "Responding to tone"],
  ["Contradiction", "Contradiction"],
  ["Contre-argument", "Counterargument"],
  ["Réfutation", "Refutation"],
  ["Réfutation du point central", "Refuting the central point"],
  ["Clara : « La ville devrait remplacer le parking de la place du marché par un jardin. Les commerces n'y perdraient rien : la plupart des clients du marché viennent à pied, d'après le comptage de l'an dernier. »", "Clara: “The town should replace the car park in the market square with a garden. Shops would lose nothing: most market customers come on foot, according to last year’s count.”"],
  ["Quelle idée ridicule, on voit bien que vous n'y connaissez rien.", "What a ridiculous idea, it’s obvious you know nothing about it."],
  ["Vous dites ça parce que vous n'avez pas de voiture.", "You only say that because you don’t have a car."],
  ["Votre ton donneur de leçons est insupportable.", "Your preachy tone is unbearable."],
  ["Non, les commerces y perdraient.", "No, the shops would lose out."],
  ["Les livreurs ont besoin de se garer près du marché, et un jardin ne le permettrait pas.", "Delivery drivers need to park near the market, and a garden wouldn’t allow that."],
  ["Vous dites « la plupart des clients viennent à pied » : le comptage a eu lieu un mardi matin, pas un samedi, jour où le marché attire surtout des clients en voiture.", "You say “most customers come on foot”: the count took place on a Tuesday morning, not a Saturday, when the market mainly attracts customers who come by car."],
  ["Tout votre raisonnement repose sur ce comptage. S'il ne représente pas les jours de forte affluence, on ne sait pas si les commerces y perdraient : il faudrait compter un samedi avant de décider.", "Your whole argument rests on that count. If it does not represent the busy days, we don’t know whether the shops would lose out: we would need to count on a Saturday before deciding."],
  ["Hugo : « Le collège devrait commencer les cours à 9 heures au lieu de 8 heures : les adolescents dorment trop peu, et le sommeil compte pour apprendre. »", "Hugo: “The school should start lessons at 9 a.m. instead of 8: teenagers get too little sleep, and sleep matters for learning.”"],
  ["N'importe quoi, comme d'habitude.", "Nonsense, as usual."],
  ["Facile à dire pour quelqu'un qui n'a jamais eu à se lever tôt.", "Easy to say for someone who has never had to get up early."],
  ["Vous prenez un ton très sûr de vous pour un simple parent d'élève.", "You sound very sure of yourself for a mere parent."],
  ["Je ne suis pas d'accord.", "I disagree."],
  ["Beaucoup de parents commencent le travail à 8 h 30 et ne pourraient plus déposer leurs enfants.", "Many parents start work at 8:30 and could no longer drop their children off."],
  ["Vous dites que les adolescents dorment trop peu ; mais s'ils se couchent plus tard quand les cours commencent plus tard, ils ne gagneront pas de sommeil.", "You say teenagers get too little sleep; but if they go to bed later when lessons start later, they won’t gain any sleep."],
  ["Votre proposition suppose qu'un début à 9 heures ferait gagner du sommeil. C'est le point à vérifier : si les adolescents décalent leur coucher d'autant, la mesure ne sert à rien, quoi qu'on pense par ailleurs du sommeil.", "Your proposal assumes that a 9 a.m. start would gain sleep. That is the point to check: if teenagers push their bedtime back by the same amount, the measure is pointless, whatever one thinks of sleep otherwise."],
  ["Quels arguments contre votre choix avez-vous cherchés ?", "What arguments against your choice have you looked for?"],
  ["Que sait-on de la fréquence habituelle de ce genre de situation ?", "What do we know about how often this kind of situation usually occurs?"],
  ["taux de base", "base rate"],
  ["Quelle était votre estimation avant d'entendre le premier chiffre ?", "What was your estimate before you heard the first figure?"],
  ["Continueriez-vous si vous n'aviez encore rien investi ?", "Would you carry on if you had not yet invested anything?"],
  ["coûts irrécupérables", "sunk costs"],
  ["Reformulez les options autrement : votre préférence change-t-elle ?", "Reword the options differently: does your preference change?"],
  ["Combien de temps des projets comparables ont-ils pris ?", "How long did comparable projects take?"],
  ["Quels avis indépendants avez-vous recueillis avant toute discussion de groupe ?", "What independent opinions did you gather before any group discussion?"],
  ["pensée de groupe", "groupthink"],
  ["Qu'attendez-vous exactement de cette décision ? Notez-le pour pouvoir la juger plus tard.", "What exactly do you expect from this decision? Write it down so you can judge it later."],
  ["biais du résultat", "outcome bias"],
  ["un débat", "a debate"],
  ["Une grille de seize sophismes à cocher pendant un débat ou un repas. Partagez l'adresse : chacun a la même grille. Elle s'imprime aussi.", "A card of sixteen fallacies to tick off during a debate or a meal. Share the address: everyone gets the same card. It can also be printed."],
  ["Qui doit prouver ?", "Who has to prove it?"],
  ["Dans un désaccord, qui doit apporter des preuves : celui qui affirme, celui qui doute, les deux, ou personne ? Dix situations.", "In a disagreement, who has to provide evidence: the one who asserts, the one who doubts, both, or no one? Ten situations."],
  ["Qui doit apporter des preuves ?", "Who has to provide evidence?"],
  ["La charge de la preuve", "The burden of proof"],
  ["C'est à celui qui affirme d'apporter des preuves, pas aux autres de démontrer qu'il a tort. Douter n'est pas affirmer le contraire : celui qui dit « je n'en sais rien » n'a rien à prouver.", "It is up to the person making a claim to provide evidence, not up to others to show they are wrong. Doubting is not asserting the opposite: someone who says “I have no idea” has nothing to prove."],
  ["Mais contester un résultat solidement établi, c'est affirmer quelque chose à son tour : il faut alors dire pourquoi les preuves existantes seraient fausses. Et pour une affaire de goût, il n'y a rien à prouver, seulement des raisons à échanger.", "But disputing a well-established result is itself making a claim: you must then say why the existing evidence would be wrong. And for a matter of taste, there is nothing to prove, only reasons to exchange."],
  ["Outils philosophiques", "Philosophical tools"],
  ["La pyramide du désaccord", "The disagreement pyramid"],
  ["De l'insulte à la réfutation du point central : sept façons de répondre à un argument. Classez quatorze répliques.", "From name-calling to refuting the central point: seven ways of responding to an argument. Sort fourteen replies."],
  ["Réponse : « {0} »", "Reply: “{0}”"],
  ["À quel étage de la pyramide est cette réponse ?", "Which level of the pyramid is this reply on?"],
  ["Monter dans la pyramide", "Moving up the pyramid"],
  ["Paul Graham propose, dans un essai de 2008 (« How to Disagree »), de classer les réponses à un désaccord : l'insulte, l'attaque personnelle, la réponse au ton, la simple contradiction, le contre-argument, la réfutation (citer ce que l'autre a dit et montrer en quoi c'est faux), enfin la réfutation du point central. C'est un essai, pas une étude, mais la grille aide à repérer les réponses qui esquivent le fond.", "Paul Graham proposes, in a 2008 essay (“How to Disagree”), a way of ranking responses to a disagreement: name-calling, ad hominem, responding to tone, simple contradiction, counterargument, refutation (quoting what the other person said and showing why it is wrong), and finally refuting the central point. It is an essay, not a study, but the framework helps spot responses that dodge the substance."],
  ["Une réponse vive peut être une bonne réfutation, et une réponse polie, une esquive : c'est le contenu qui compte, pas le ton.", "A sharp reply can be a good refutation, and a polite one a dodge: what counts is the content, not the tone."],
  ["Diversion", "Diversion"],
  ["Débattre honnêtement", "Debating honestly"],
  ["Réponse", "Reply"],
  ["Décision guidée", "Guided decision"],
  ["Une décision importante à prendre ? Huit questions pour l'examiner, ce que vous en attendez, et une date pour en faire le bilan.", "An important decision to make? Eight questions to examine it, what you expect from it, and a date to review it."],
  ["Bilan à faire", "Review due"],
  ["Ce que vous attendiez : « {0} »", "What you expected: “{0}”"],
  ["non noté", "not recorded"],
  ["Qu'est-il arrivé ?", "What happened?"],
  ["Avec ce que vous saviez alors, la décision était-elle bonne, quel que soit le résultat ?", "Given what you knew at the time, was the decision a good one, whatever the outcome?"],
  ["Bonne décision", "Good decision"],
  ["Mauvaise décision", "Bad decision"],
  ["Nouvelle décision", "New decision"],
  ["La décision à prendre", "The decision to make"],
  ["Examiner cette décision", "Examine this decision"],
  ["Noter", "Note it"],
  ["En savoir plus : {0}", "Learn more: {0}"],
  ["Date du bilan", "Review date"],
  ["Choisissez une date où vous pourrez juger la décision : le bilan vous attendra ici, et vous pourrez l'ajouter à votre agenda.", "Choose a date by which you can judge the decision: the review will wait for you here, and you can add it to your calendar."],
  ["Enregistrer", "Save"],
  ["Décision enregistrée. Bilan prévu le {0}.", "Decision saved. Review scheduled for {0}."],
  ["Ajouter le bilan à mon agenda", "Add the review to my calendar"],
  ["Bilan de décision : {0}", "Decision review: {0}"],
  ["Faites le bilan sur {0}", "Do the review at {0}"],
  ["Juger la décision, pas seulement le résultat", "Judge the decision, not just the outcome"],
  ["Une bonne décision peut mal tourner, et une mauvaise réussir par chance. Noter avant ce que l'on sait et ce que l'on attend permet, au bilan, de juger la décision avec les informations qu'on avait, sans le biais rétrospectif ni le biais du résultat.", "A good decision can turn out badly, and a bad one can succeed by luck. Writing down beforehand what you know and what you expect lets you, at the review, judge the decision with the information you had, free of hindsight bias and outcome bias."],
  ["Avant une décision importante", "Before an important decision"],
  ["Retour à mes décisions", "Back to my decisions"],
  ["Vos décisions", "Your decisions"],
  ["bilan fait : {0}", "review done: {0}"],
  ["bonne décision", "good decision"],
  ["mauvaise décision", "bad decision"],
  ["bilan le {0}", "review on {0}"],
  ["une fermeture éclair", "a zip"],
  ["Que fait le curseur quand on le fait glisser vers le haut ?", "What does the slider do when you pull it up?"],
  ["Ses deux gorges, qui se rejoignent, rapprochent les dents décalées des deux bandes et les engrènent", "Its two channels, which converge, bring the staggered teeth of the two tapes together and interlock them"],
  ["Il presse les dents l'une contre l'autre, et elles tiennent par simple frottement", "It presses the teeth against each other, and they hold together by friction alone"],
  ["Il accroche chaque dent à un œillet placé en face, sur l'autre bande", "It hooks each tooth onto an eyelet opposite, on the other tape"],
  ["Il tord légèrement chaque dent, qui se bloque ensuite contre sa voisine", "It slightly twists each tooth, which then locks against its neighbour"],
  ["Deux bandes de tissu portent des dents, décalées d'une bande à l'autre. Le curseur a deux gorges qui se rejoignent : en montant, il guide les dents des deux bandes l'une vers l'autre et les engrène ; en descendant, il les sépare.", "Two fabric tapes carry teeth, staggered from one tape to the other. The slider has two channels that converge: going up, it guides the teeth of the two tapes towards each other and interlocks them; going down, it separates them."],
  ["Wikipédia, « Fermeture à glissière ».", "Wikipedia, “Zipper”."],
  ["un réfrigérateur", "a refrigerator"],
  ["D'où vient le froid à l'intérieur ?", "Where does the cold inside come from?"],
  ["Un fluide s'y évapore en prenant de la chaleur ; comprimé, il se condense à l'arrière, où il la rejette", "A fluid evaporates inside, absorbing heat; compressed, it condenses at the back, where it releases it"],
  ["Le moteur produit de l'air froid, qu'un ventilateur souffle à l'intérieur", "The motor produces cold air, which a fan blows inside"],
  ["Un gaz très froid, chargé en usine, se réchauffe lentement au fil des années", "A very cold gas, charged at the factory, slowly warms up over the years"],
  ["Les parois isolantes absorbent la chaleur des aliments", "The insulating walls absorb the heat from the food"],
  ["Le réfrigérateur ne fabrique pas de froid : il déplace de la chaleur. Un fluide frigorigène s'évapore dans l'appareil en prenant de la chaleur ; le compresseur le comprime, ce qui l'échauffe ; il se condense dans la grille ou les tuyaux de l'arrière, où il cède cette chaleur à la pièce, puis revient s'évaporer.", "A refrigerator does not make cold: it moves heat. A refrigerant evaporates inside the appliance, absorbing heat; the compressor compresses it, which heats it up; it condenses in the coil or pipes at the back, where it gives that heat up to the room, then returns to evaporate."],
  ["Wikipédia, « Réfrigérateur ».", "Wikipedia, “Refrigerator”."],
  ["une chasse d'eau", "a toilet flush"],
  ["Qu'est-ce qui arrête le remplissage du réservoir ?", "What stops the cistern from filling?"],
  ["Le flotteur, qui remonte avec le niveau de l'eau et referme le robinet d'arrivée", "The float, which rises with the water level and closes the inlet valve"],
  ["Une minuterie, réglée sur la contenance du réservoir", "A timer, set to the capacity of the cistern"],
  ["La pression de l'eau accumulée, qui repousse l'eau du tuyau d'arrivée", "The pressure of the accumulated water, which pushes back the water in the supply pipe"],
  ["L'obturateur, qui en retombant au fond coupe aussi l'arrivée d'eau", "The flapper, which on falling back to the bottom also cuts off the water supply"],
  ["Le levier soulève l'obturateur du fond du réservoir : l'eau descend dans la cuvette en quelques secondes et l'obturateur se repose. Le flotteur, descendu avec le niveau, a ouvert le robinet d'arrivée ; en remontant avec l'eau, il le referme. Un tube de trop-plein évacue l'eau si le flotteur ferme mal.", "The lever lifts the flapper from the bottom of the cistern: the water flows into the bowl in a few seconds and the flapper settles back. The float, having dropped with the level, has opened the inlet valve; rising with the water, it closes it again. An overflow tube drains the water if the float fails to shut properly."],
  ["Wikipédia, « Chasse d'eau ».", "Wikipedia, “Flush toilet”."],
  ["une serrure à clé plate (serrure à goupilles)", "a flat-key lock (pin tumbler lock)"],
  ["Pourquoi le cylindre ne tourne-t-il qu'avec la bonne clé ?", "Why does the cylinder turn only with the right key?"],
  ["Des goupilles poussées par des ressorts le bloquent ; seule la bonne clé les aligne toutes à la limite du cylindre", "Spring-loaded pins block it; only the right key lines them all up at the shear line of the cylinder"],
  ["La clé contient un code magnétique que la serrure lit", "The key contains a magnetic code that the lock reads"],
  ["Les crans de la clé s'emboîtent dans des encoches du cylindre, comme un engrenage", "The key’s notches fit into recesses in the cylinder, like a gear"],
  ["La clé pousse directement le pêne, à condition d'avoir la bonne longueur", "The key pushes the bolt directly, provided it is the right length"],
  ["Des paires de goupilles, poussées par des ressorts, traversent à la fois le cylindre et le corps de la serrure, et l'empêchent de tourner. Chaque cran de la clé soulève une paire à une hauteur précise : avec la bonne clé, toutes les séparations s'alignent sur la limite du cylindre, qui peut alors tourner. Un cran trop court ou trop long laisse une goupille en travers.", "Pairs of pins, pushed by springs, pass through both the cylinder and the body of the lock and stop it from turning. Each cut in the key lifts a pair to a precise height: with the right key, all the gaps between the pins line up with the edge of the cylinder, which can then turn. A cut that is too shallow or too deep leaves a pin straddling the line."],
  ["Wikipédia, « Serrure à goupilles ».", "Wikipedia, “Pin tumbler lock”."],
  ["un vélo", "a bicycle"],
  ["Que relie la chaîne ?", "What does the chain connect?"],
  ["Le plateau du pédalier au pignon de la roue arrière", "The chainring of the crankset to the sprocket of the rear wheel"],
  ["Le pédalier aux deux roues", "The crankset to both wheels"],
  ["La roue avant à la roue arrière", "The front wheel to the rear wheel"],
  ["Le pédalier à la roue avant", "The crankset to the front wheel"],
  ["Les pédales font tourner le plateau du pédalier ; la chaîne transmet ce mouvement au pignon de la roue arrière, seule motrice. La roue avant, libre, sert à diriger : une chaîne qui la relierait empêcherait de tourner le guidon.", "The pedals turn the chainring; the chain transmits this movement to the sprocket of the rear wheel, the only driven one. The front wheel, free, is for steering: a chain connecting it would stop you turning the handlebars."],
  ["Wikipédia, « Bicyclette ».", "Wikipedia, “Bicycle”."],
  ["Comprenez-vous vraiment ?", "Do you really understand?"],
  ["Notez votre compréhension de cinq objets du quotidien, puis expliquez-en trois pas à pas et répondez à une question sur chacun. Votre note change-t-elle ?", "Rate your understanding of five everyday objects, then explain three of them step by step and answer a question about each. Does your rating change?"],
  ["Je n'en ai qu'une idée vague", "I only have a vague idea"],
  ["Je pourrais l'expliquer en détail", "I could explain it in detail"],
  ["Comment comprenez-vous le fonctionnement d'{0} ?", "How well do you understand how {0} works?"],
  ["Expliquez, étape par étape, comment fonctionne {0}.", "Explain, step by step, how {0} works."],
  ["Écrivez comme pour quelqu'un qui n'en a jamais vu : chaque pièce, et ce qu'elle fait. Personne d'autre ne lira votre texte.", "Write as if for someone who has never seen one: each part, and what it does. No one else will read your text."],
  ["Votre explication", "Your explanation"],
  ["J'ai fini", "I’m done"],
  ["Après avoir écrit votre explication, comment jugez-vous maintenant votre compréhension ?", "Having written your explanation, how do you now rate your understanding?"],
  ["Pas tout à fait.", "Not quite."],
  ["Et maintenant, comment jugez-vous votre compréhension de départ ?", "And now, how do you rate the understanding you started with?"],
  ["{0} / {1} aux questions", "{0} / {1} on the questions"],
  ["Vos notes, avant d'expliquer, après l'explication, puis après la question :", "Your ratings, before explaining, after the explanation, then after the question:"],
  ["Votre note n'a baissé pour aucun des trois objets : votre première estimation était peut-être déjà prudente.", "Your rating did not drop for any of the three objects: your first estimate was perhaps already cautious."],
  ["Votre note a baissé pour {0}. Une baisse est le résultat le plus fréquent.", "Your rating dropped for {0}. A drop is the most common result."],
  ["les trois objets", "all three objects"],
  ["deux des trois objets", "two of the three objects"],
  ["un des trois objets", "one of the three objects"],
  ["L'illusion de profondeur explicative", "The illusion of explanatory depth"],
  ["Rozenblit et Keil (2002) ont fait noter à des étudiants leur compréhension d'objets courants (fermeture éclair, chasse d'eau, serrure à cylindre…), puis la leur ont fait expliquer pas à pas et répondre à une question précise. Leurs notes ont baissé après l'explication, puis encore après la question : nous confondons la familiarité avec un objet et la compréhension de son mécanisme. Cette illusion est plus forte pour les mécanismes que pour les faits (une capitale) ou les procédures (une recette).", "Rozenblit and Keil (2002) had students rate their understanding of common objects (zip, flush toilet, cylinder lock…), then had them explain step by step and answer a specific question. Their ratings dropped after the explanation, then again after the question: we confuse familiarity with an object with understanding of its mechanism. This illusion is stronger for mechanisms than for facts (a capital city) or procedures (a recipe)."],
  ["Lawson (2006) a demandé de compléter le dessin d'un vélo : beaucoup de participants ont commis des erreurs graves, comme faire passer la chaîne autour de la roue avant aussi bien que de la roue arrière.", "Lawson (2006) asked people to complete a drawing of a bicycle: many participants made serious mistakes, such as running the chain around the front wheel as well as the rear wheel."],
  ["Fernbach et ses collègues (2013) ont trouvé qu'expliquer le détail d'une politique publique rendait les avis moins tranchés. Mais Crawford et Ruscio (2021), en trois réplications préenregistrées, n'ont pas retrouvé cet effet sur la modération des opinions : la baisse de la compréhension ressentie, elle, reste bien établie.", "Fernbach and colleagues (2013) found that explaining the details of a public policy made opinions less extreme. But Crawford and Ruscio (2021), in three preregistered replications, did not find this effect on moderating opinions: the drop in felt understanding, however, remains well established."],
  ["Conclusion", "Conclusion"],
  ["Raison", "Reason"],
  ["Objection", "Objection"],
  ["Réponse à une objection", "Response to an objection"],
  ["Hors sujet", "Off topic"],
  ["La rue du Marché", "Market Street"],
  ["La rue du Marché date du XVIIIe siècle.", "Market Street dates from the 18th century."],
  ["La commune devrait la rendre piétonne.", "The council should make it pedestrian-only."],
  ["Le bruit et la pollution des voitures y gênent les riverains chaque jour.", "Traffic noise and pollution trouble residents every day."],
  ["Dans les rues voisines rendues piétonnes, les commerçants disent avoir gagné des clients.", "In neighbouring streets that have been pedestrianised, shopkeepers say they have gained customers."],
  ["On objectera que les livraisons deviendraient impossibles.", "It will be objected that deliveries would become impossible."],
  ["Pourtant, des créneaux de livraison tôt le matin suffisent dans les rues voisines.", "Yet early-morning delivery slots are enough in the neighbouring streets."],
  ["Les entraînements du soir", "The evening training sessions"],
  ["Le club de natation devrait avancer ses entraînements du soir de 20 heures à 18 heures.", "The swimming club should bring its evening training sessions forward from 8 p.m. to 6 p.m."],
  ["À 20 heures, beaucoup de jeunes nageurs arrivent fatigués et se couchent tard.", "At 8 p.m., many young swimmers arrive tired and go to bed late."],
  ["De plus, le bassin est libre dès 18 heures depuis que l'aquagym a changé d'horaire.", "Moreover, the pool has been free from 6 p.m. since the aqua aerobics class changed its time."],
  ["Certes, des parents qui travaillent jusqu'à 18 heures ne pourront plus accompagner leurs enfants.", "Admittedly, parents who work until 6 p.m. will no longer be able to bring their children."],
  ["Mais un covoiturage entre familles, déjà proposé par plusieurs parents, réglerait la plupart des cas.", "But a car share between families, already offered by several parents, would solve most cases."],
  ["Le club fêtera ses quarante ans l'an prochain.", "The club will celebrate its fortieth anniversary next year."],
  ["La bibliothèque le dimanche", "The library on Sundays"],
  ["Près d'un inscrit sur trois a un emploi en semaine, d'après le registre de la bibliothèque.", "Nearly one in three members works during the week, according to the library’s register."],
  ["Pour beaucoup d'inscrits, le dimanche est donc le seul jour où venir.", "For many members, Sunday is therefore the only day they can come."],
  ["C'est pourquoi la bibliothèque doit rester ouverte le dimanche.", "That is why the library must stay open on Sundays."],
  ["Ouvrir le dimanche coûte cher en heures majorées, répondra-t-on.", "It will be replied that opening on Sundays is expensive because of overtime pay."],
  ["Fermer le lundi matin, où presque personne ne vient, compenserait ce coût.", "Closing on Monday mornings, when almost nobody comes, would offset this cost."],
  ["La bibliothèque a été repeinte au printemps.", "The library was repainted in the spring."],
  ["Les téléphones en classe", "Phones in class"],
  ["Les notifications interrompent l'attention, même quand on n'y répond pas.", "Notifications interrupt attention, even when you do not respond to them."],
  ["Les téléphones ont beaucoup changé en vingt ans.", "Phones have changed a lot in twenty years."],
  ["Le collège devrait donc demander aux élèves de déposer leur téléphone à l'entrée des salles.", "The school should therefore ask pupils to leave their phones at the classroom door."],
  ["Mais, disent certains, les élèves en ont besoin pour prévenir leurs parents.", "But, some say, pupils need them to let their parents know."],
  ["Ils le récupèrent à chaque pause, et le secrétariat peut joindre les familles en cas d'urgence.", "They get them back at every break, and the school office can reach families in an emergency."],
  ["Hors de l'arbre : {0} Ces phrases ne soutiennent ni ne contestent rien.", "Outside the tree: {0} These sentences neither support nor contest anything."],
  ["Démonter un argument", "Taking an argument apart"],
  ["Un court texte fictif, phrase par phrase : conclusion, raison, objection, réponse ou hors sujet ? Puis l'arbre de l'argument apparaît.", "A short fictitious text, sentence by sentence: conclusion, reason, objection, response or off topic? Then the argument tree appears."],
  ["« {0} » (texte fictif)", "“{0}” (fictitious text)"],
  ["Quel est le rôle de la phrase surlignée ?", "What is the role of the highlighted sentence?"],
  ["C'est la thèse que tout le texte veut établir.", "It is the thesis that the whole text aims to establish."],
  ["Elle soutient :", "It supports:"],
  ["Elle conteste :", "It challenges:"],
  ["Elle répond à l'objection :", "It answers the objection:"],
  ["Elle ne soutient ni ne conteste rien : la retirer ne change pas l'argument.", "It neither supports nor challenges anything: removing it does not change the argument."],
  ["L'arbre de l'argument", "The argument tree"],
  ["Lire la structure avant de juger", "Read the structure before judging"],
  ["Un argument se compose d'une conclusion et des raisons qui la soutiennent ; un bon texte examine aussi les objections et y répond. Les mots de liaison (« donc », « c'est pourquoi », « certes », « mais ») guident, mais l'ordre des phrases ne suit pas toujours la logique : la conclusion n'est pas forcément au début.", "An argument consists of a conclusion and the reasons that support it; a good text also examines objections and answers them. Linking words (“therefore”, “that is why”, “admittedly”, “but”) guide the reader, but the order of the sentences does not always follow the logic: the conclusion is not necessarily at the start."],
  ["Dessiner l'arbre permet de voir ce qui porte la conclusion. On peut alors vérifier chaque raison, repérer une objection restée sans réponse, et écarter ce qui ne fait que remplir le texte.", "Drawing the tree shows what holds up the conclusion. You can then check each reason, spot an objection left unanswered, and set aside what merely fills out the text."],
  ["Hareng rouge", "Red herring"],
  ["Homme de paille", "Straw man"],
  ["Un autre argument", "Another argument"],
  ["Phrase", "Sentence"],
  ["Fiable pour cette information", "Reliable for this claim"],
  ["Engagé : à croiser avec d'autres sources", "Partisan: cross-check with other sources"],
  ["Peu fiable", "Unreliable"],
  ["Observatoire européen de la nutrition de l'enfant", "European Observatory on Child Nutrition"],
  ["« Aucune étude sérieuse ne montre que les boissons sucrées favorisent le surpoids des enfants. »", "“No serious study shows that sugary drinks contribute to children being overweight.”"],
  ["Un logo sobre, une adresse en .org, un comité scientifique de douze membres présentés avec leurs titres, une rubrique « Nos publications » bien fournie et une charte d'indépendance en pied de page.", "A sober logo, a .org address, a scientific committee of twelve members presented with their titles, a well-stocked “Our publications” section and an independence charter in the footer."],
  ["Un registre public des représentants d'intérêts : l'Observatoire y est financé à 90 % par une fédération de fabricants de boissons.", "A public register of lobbyists: the Observatory is listed there as 90% funded by a federation of drinks manufacturers."],
  ["Un article d'un quotidien national : son président a dirigé pendant dix ans le service marketing d'un fabricant de sodas.", "An article in a national daily: its president spent ten years running the marketing department of a soft-drinks manufacturer."],
  ["Une revue de synthèse universitaire sur le sujet, qui conclut au contraire à un lien entre boissons sucrées et surpoids.", "A university review of the subject, which concludes, on the contrary, that there is a link between sugary drinks and being overweight."],
  ["Le site soigne toutes les apparences d'un organisme scientifique, mais il est financé par les fabricants concernés, sans le dire, et contredit les synthèses indépendantes. Rien de cela ne se voyait en restant sur le site.", "The site takes care over every appearance of a scientific body, but it is funded by the manufacturers concerned, without saying so, and contradicts independent reviews. None of this was visible from staying on the site."],
  ["Le Courrier de la Vallée", "The Valley Courier"],
  ["« Le pont de la départementale sera fermé trois semaines à partir du 4 mars pour travaux. »", "“The bridge on the county road will be closed for three weeks from 4 March for roadworks.”"],
  ["Une mise en page datée, des publicités envahissantes, des photos de qualité inégale. La page « Qui sommes-nous » se limite à une adresse et un numéro de téléphone.", "A dated layout, intrusive adverts, photos of uneven quality. The “About us” page is limited to an address and a phone number."],
  ["Une encyclopédie en ligne : quotidien régional fondé il y a plus de soixante-dix ans, avec une rédaction d'une trentaine de journalistes.", "An online encyclopedia: a regional daily founded more than seventy years ago, with a newsroom of about thirty journalists."],
  ["Le site de la préfecture fictive du département : l'arrêté de fermeture du pont, aux mêmes dates.", "The website of the county’s (fictitious) prefecture: the order closing the bridge, for the same dates."],
  ["Plusieurs médias régionaux qui citent régulièrement ses informations locales.", "Several regional media outlets that regularly cite its local reporting."],
  ["L'apparence du site est peu engageante, mais il s'agit d'un journal établi, et l'information est confirmée par la source officielle. La qualité de la mise en page ne dit rien de la fiabilité.", "The site looks unappealing, but it is an established newspaper, and the information is confirmed by the official source. The quality of the layout says nothing about reliability."],
  ["Santé Nature Vérité", "Health, Nature, Truth"],
  ["« Une cure de vitamine C à haute dose guérit la grippe en quarante-huit heures. »", "“A high-dose vitamin C course cures flu in forty-eight hours.”"],
  ["Des témoignages chaleureux, un médecin en blouse blanche sur la page d'accueil, des références à des « études récentes » et un bandeau « Information libre et indépendante ».", "Warm testimonials, a doctor in a white coat on the home page, references to “recent studies” and a banner reading “Free and independent information”."],
  ["Un service public d'enregistrement des noms de domaine : site créé il y a huit mois, propriétaire anonyme.", "A public domain-name registration service: site created eight months ago, anonymous owner."],
  ["Un site de vérification des faits : plusieurs de ses articles ont été démentis ; le médecin de la photo est une image vendue par une banque d'images.", "A fact-checking site: several of its articles have been debunked; the doctor in the photo is an image sold by a stock photo library."],
  ["Une boutique en ligne liée au site, qui vend des compléments de vitamine C.", "An online shop linked to the site, which sells vitamin C supplements."],
  ["Le site vend les produits qu'il recommande, son auteur est inconnu et ses affirmations ont déjà été démenties. Le mot « indépendant » sur un site ne prouve rien : c'est ce que d'autres disent de lui qui compte.", "The site sells the products it recommends, its author is unknown and its claims have already been debunked. The word “independent” on a site proves nothing: what counts is what others say about it."],
  ["Laboratoire d'hydrologie de l'université de Valmont", "Valmont University Hydrology Laboratory"],
  ["« Le niveau moyen de la nappe phréatique de la région a baissé de deux mètres en trente ans. »", "“The average groundwater level in the region has dropped by two metres in thirty years.”"],
  ["Une page austère, une liste de chercheurs avec leurs publications, des jeux de données téléchargeables et la méthode de mesure décrite en détail.", "An austere page, a list of researchers with their publications, downloadable datasets and the measurement method described in detail."],
  ["Une encyclopédie en ligne : l'université fictive de Valmont est un établissement public ; le laboratoire est rattaché à un organisme national de recherche.", "An online encyclopedia: the fictitious University of Valmont is a public institution; the laboratory is attached to a national research organisation."],
  ["Une revue scientifique à comité de lecture, qui a publié l'étude sur la nappe phréatique.", "A peer-reviewed scientific journal, which published the study on the groundwater."],
  ["Un article de presse régionale qui cite l'étude et interroge un hydrologue d'un autre laboratoire, qui juge les mesures solides.", "A regional press article that cites the study and interviews a hydrologist from another laboratory, who judges the measurements to be sound."],
  ["Laboratoire public, étude publiée dans une revue à comité de lecture et jugée solide par un spécialiste extérieur : pour cette information, la source est fiable.", "Public laboratory, study published in a peer-reviewed journal and judged sound by an outside specialist: for this claim, the source is reliable."],
  ["Institut pour la liberté d'entreprendre", "Institute for Free Enterprise"],
  ["« Baisser les impôts sur les entreprises augmenterait l'emploi de 3 % en cinq ans. »", "“Cutting corporate taxes would increase employment by 3% over five years.”"],
  ["Un site professionnel, des rapports en PDF avec graphiques, des « chercheurs associés » et une citation d'un prix Nobel d'économie en page d'accueil.", "A professional-looking site, PDF reports with charts, “associate researchers” and a quotation from a Nobel laureate in economics on the home page."],
  ["Une encyclopédie en ligne : groupe de réflexion qui défend ouvertement la baisse des impôts et la réduction de la dépense publique ; ses financeurs sont des entreprises et des fondations privées, dont la liste est publiée.", "An online encyclopedia: a think tank that openly advocates tax cuts and reduced public spending; its funders are companies and private foundations, whose list is published."],
  ["Un article de presse économique : son chiffre de 3 % vient d'un modèle fondé sur des hypothèses favorables ; d'autres économistes obtiennent un effet bien plus faible.", "An economic press article: its figure of 3% comes from a model based on favourable assumptions; other economists find a much smaller effect."],
  ["Les rapports d'un organisme public de prévision, qui donnent une fourchette large et incertaine.", "The reports of a public forecasting body, which give a wide and uncertain range."],
  ["Ce groupe ne cache ni son orientation ni ses financeurs : ses rapports peuvent être utiles, mais ils défendent une thèse. Son chiffre est l'hypothèse haute d'un débat ; il faut le croiser avec des sources aux positions différentes.", "This group hides neither its orientation nor its funders: its reports can be useful, but they defend a thesis. Its figure is the high end of a debate; it needs to be cross-checked with sources taking different positions."],
  ["Collectif citoyen pour l'air pur", "Citizens’ Collective for Clean Air"],
  ["« La pollution de l'air près de l'école des Tilleuls dépasse les seuils recommandés trois jours sur quatre. »", "“Air pollution near the Tilleuls school exceeds recommended thresholds three days out of four.”"],
  ["Un site militant, des photos de manifestations, des appels à signer une pétition et un ton alarmé.", "An activist site, photos of demonstrations, calls to sign a petition and an alarmed tone."],
  ["Le site de l'organisme régional de surveillance de la qualité de l'air : sa station la plus proche, à deux kilomètres, ne dépasse les seuils qu'un jour sur dix.", "The website of the regional air-quality monitoring body: its nearest station, two kilometres away, exceeds the thresholds only one day in ten."],
  ["Un article de presse locale : le collectif a installé ses propres capteurs bon marché devant l'école ; un ingénieur rappelle que leurs mesures peuvent être faussées par l'humidité.", "A local press article: the collective installed its own cheap sensors in front of the school; an engineer points out that their readings can be distorted by humidity."],
  ["Un rapport du même organisme régional, qui juge utile une campagne de mesure près de l'école, faute de station sur place.", "A report from the same regional body, which considers a measurement campaign near the school worthwhile, given the lack of a station on site."],
  ["Le collectif défend une cause et ses capteurs sont imprécis, mais la question est légitime et la station officielle est loin. Ni à rejeter, ni à croire telle quelle : il faut croiser, et attendre des mesures fiables sur place.", "The collective champions a cause and its sensors are imprecise, but the question is legitimate and the official station is far away. Neither to be dismissed nor taken at face value: cross-check, and wait for reliable on-site measurements."],
  ["Lecture latérale", "Lateral reading"],
  ["Quatre sites fictifs, une affirmation chacun. Rester sur le site pour l'examiner, ou chercher ce que d'autres en disent ? Puis jugez leur fiabilité.", "Four fictitious sites, one claim each. Stay on the site to examine it, or look up what others say about it? Then judge how reliable they are."],
  ["Site fictif : « {0} »", "Fictitious site: “{0}”"],
  ["Examiner le site", "Examine the site"],
  ["Chercher ce que d'autres en disent", "Look up what others say about it"],
  ["Sur le site", "On the site"],
  ["Ailleurs, en cherchant le nom du site (résultats fictifs)", "Elsewhere, by searching for the site’s name (fictitious results)"],
  ["Votre jugement sur cette source", "Your judgement of this source"],
  ["Vous avez cherché ce que d'autres disaient du site avant de juger pour aucun des {0} sites.", "For none of the {0} sites did you look up what others said before judging."],
  ["Vous avez cherché ce que d'autres disaient du site avant de juger pour les {0} sites.", "For all {0} sites, you looked up what others said before judging."],
  ["Vous avez cherché ce que d'autres disaient du site avant de juger pour {0} sites sur {1}.", "For {0} of the {1} sites, you looked up what others said before judging."],
  ["Lire en largeur, pas en profondeur", "Reading laterally, not vertically"],
  ["Wineburg et McGrew (2019) ont observé 45 internautes expérimentés évaluer des sites réels : 10 historiens docteurs, 10 vérificateurs de faits professionnels et 25 étudiants de Stanford. Historiens et étudiants restaient sur le site et se laissaient souvent prendre à des signes faciles à imiter : logo officiel, nom de domaine, présentation soignée. Les vérificateurs, eux, quittaient le site après un coup d'œil et ouvraient d'autres onglets pour savoir qui était derrière : ils arrivaient à des conclusions mieux fondées, bien plus vite.", "Wineburg and McGrew (2019) observed 45 experienced internet users evaluating real sites: 10 PhD historians, 10 professional fact-checkers and 25 Stanford students. Historians and students stayed on the site and were often taken in by easily imitated signs: an official-looking logo, a domain name, polished presentation. The fact-checkers, for their part, left the site after a glance and opened other tabs to find out who was behind it: they reached better-founded conclusions, much faster."],
  ["La question utile n'est pas « ce site a-t-il l'air sérieux ? » mais « que disent de lui des sources indépendantes ? » : qui le finance, qui l'écrit, que vaut ce qu'il avance ailleurs.", "The useful question is not “does this site look serious?” but “what do independent sources say about it?”: who funds it, who writes it, how reliable is what it claims elsewhere."],
  ["Effet de halo", "Halo effect"],
  ["D'autres sites", "Other sites"],
  ["Site", "Site"],
  ["2 × 8 min", "2 × 8 min"],
  ["Bilan avant et après", "Before-and-after assessment"],
  ["Vingt situations à identifier maintenant, vingt autres sur les mêmes notions dans quelques semaines : avez-vous progressé ?", "Twenty situations to identify now, twenty others on the same concepts in a few weeks: have you improved?"],
  ["La forme A se passe au début ; la forme B, sur les mêmes vingt notions avec d'autres situations, après quelques semaines de pratique. Ces deux formes n'ont pas été validées : rien ne garantit qu'elles soient de même difficulté, et un écart de quelques points peut tenir au hasard.", "Form A is taken at the start; Form B, on the same twenty concepts with different situations, after a few weeks of practice. These two forms have not been validated: nothing guarantees that they are equally difficult, and a gap of a few points may be down to chance."],
  ["Forme {0} : {1} / 20, le {2}.", "Form {0}: {1} / 20, on {2}."],
  ["Un écart de 3 points ou moins ne permet pas de conclure : avec 20 questions, il est à la portée du hasard.", "A gap of 3 points or fewer does not allow a conclusion: with 20 questions, chance can easily produce it."],
  ["Un progrès net, sous réserve que les deux formes soient de difficulté comparable.", "A clear improvement, provided that the two forms are of comparable difficulty."],
  ["Un recul net : la forme B est peut-être plus difficile, ou certaines notions se sont effacées.", "A clear decline: Form B may be harder, or some concepts may have faded."],
  ["Pour mesurer un progrès, attendez de préférence deux semaines au moins après la forme A, en pratiquant entre-temps.", "To measure improvement, preferably wait at least two weeks after Form A, practising in the meantime."],
  ["Commencer la forme {0}", "Start Form {0}"],
  ["Effacer et recommencer", "Erase and start over"],
  ["Quel biais cette situation illustre-t-elle ?", "Which bias does this situation illustrate?"],
  ["Quel sophisme cette situation illustre-t-elle ?", "Which fallacy does this situation illustrate?"],
  ["Forme {0}", "Form {0}"],
  ["Revenez dans quelques semaines pour la forme B. Vous pouvez noter la date dans votre agenda.", "Come back in a few weeks for Form B. You can note the date in your calendar."],
  ["Ajouter un rappel à l'agenda", "Add a reminder to the calendar"],
  ["Esprit critique : bilan, forme B", "Esprit critique: assessment, Form B"],
  ["Mesurer un progrès", "Measuring improvement"],
  ["Repasser le même test mesure surtout le souvenir des réponses. Deux formes parallèles évitent cet écueil, à condition d'être aussi difficiles l'une que l'autre, ce qui se vérifie d'ordinaire en les faisant passer à de nombreuses personnes. Ces deux formes-ci ne l'ont pas été : prenez l'écart comme une indication, pas comme une mesure.", "Retaking the same test mainly measures memory of the answers. Two parallel forms avoid this pitfall, provided they are equally difficult, which is usually checked by giving them to many people. These two forms have not been: take the gap as an indication, not a measurement."],
  ["Retour au bilan", "Back to the assessment"],
  ["l'humeur", "mood"],
  ["{0} : {1} sur 7", "{0}: {1} out of 7"],
  ["« {0} »", "“{0}”"]
]);
